1	import { Metadata } from 'next';
2	import { notFound, permanentRedirect } from 'next/navigation';
3	import { TableName } from 'prisma/generated/browser';
4	import { TableNameSchema } from 'prisma/zod/schemas';
5	import { PlayerRecordType } from 'prisma/zod/schemas/models/PlayerRecord.schema';
6	import { cache } from 'react';
7	import z from 'zod';
8	
9	import { sendEmail } from '@/actions/sendEmail';
10	import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
11	import { PlayerProfile } from '@/components/PlayerProfile/PlayerProfile';
12	import { getUserRole } from '@/lib/auth.server';
13	import clubSupporterService from '@/services/ClubSupporter';
14	import countrySupporterService from '@/services/CountrySupporter';
15	import outcomeService from '@/services/Outcome';
16	import playerService from '@/services/Player';
17	import playerRecordService from '@/services/PlayerRecord';
18	import { FootyChannel } from '@/types/FootyChannel';
19	
20	interface PageProps {
21	    params: Promise<{
22	        id: string,
23	    }>,
24	    searchParams?: Promise<{
25	        year?: string;
26	    }>;
27	}
28	
29	/**
30	 * Unpacks and validates page parameters and search parameters for a player
31	 * page.
32	 *
33	 * This function performs the following operations:
34	 * - Extracts and validates the player ID (either numeric or login string)
35	 * - Retrieves the player from the database
36	 * - Validates the requested year against the player's active years
37	 * - Constructs canonical URLs and redirects if the current URL doesn't match
38	 * - Returns the player data, selected year, and all active years
39	 *
40	 * @param params - The page route parameters containing the player ID
41	 * @param searchParams - The URL search parameters, optionally containing a year
42	 * filter
43	 * @returns A promise resolving to an object containing the player record,
44	 * selected year, and array of active years
45	 * @throws {notFound} When the player is not found or the requested year is
46	 * invalid
47	 * @throws {permanentRedirect} When the current URL doesn't match the canonical
48	 * URL format
49	 */
50	const unpackParams = cache(async (
51	    params: PageProps['params'],
52	    searchParams: PageProps['searchParams'],
53	) => {
54	    const { id } = await params;
55	
56	    const resolvedSearchParams = await searchParams;
57	    const playerId = z.coerce.number().int().min(1).safeParse(id);
58	    const player = await (playerId.success ?
59	        playerService.getById(playerId.data) :
60	        playerService.getByLogin(id));
61	    if (!player) notFound();
62	
63	    const activeYears = await playerService.getYearsActive(player.id);
64	    const yearResult = z.coerce.number().int().min(0).safeParse(resolvedSearchParams?.year ?? 0);
65	    const year = yearResult.success ? yearResult.data : undefined;
66	    if (year === undefined || !activeYears.includes(year)) notFound();
67	
68	    const canonicalSearch = year ? `?year=${year}` : '';
69	    const canonicalUrl = `/footy/player/${player.id}${canonicalSearch}`;
70	    const currentSearch = resolvedSearchParams?.year ? `?year=${resolvedSearchParams.year}` : '';
71	    const currentUrl = `/footy/player/${id}${currentSearch}`;
72	    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);
73	
74	    return { player, year, activeYears };
75	});
76	
77	/**
78	 * Generates metadata for the player page.
79	 * @param props - The page props containing player ID and optional year
80	 * parameters
81	 * @returns A promise that resolves to metadata object with the player name and
82	 * year in the title
83	 */
84	export async function generateMetadata(props: PageProps): Promise<Metadata> {
85	    const { player, year } = await unpackParams(props.params, props.searchParams);
86	
87	    return {
88	        title: `${player.name}: ${year || 'All-time'}`,
89	    };
90	}
91	
92	const PlayerPage = async (props: PageProps) => {
93	    const { player, year, activeYears } = await unpackParams(props.params, props.searchParams);
94	
95	    const role = await getUserRole();
96	    const isAuthenticated = role !== 'none';
97	    const isAdmin = role === 'admin';
98	    const [
99	        introducedBy,
100	        lastPlayed,
101	        lastWon,
102	        history,
103	        clubs,
104	        countries,
105	        record,
106	        prevPlayer,
107	        nextPlayer,
108	        playerData,
109	    ] = await Promise.all([
110	        player.introducedBy != null ? playerService.getById(player.introducedBy) : Promise.resolve(null),
111	        playerService.getLastResult(player.id, year),
112	        playerService.getLastResult(player.id, year, 3),
113	        outcomeService.getHistoryByPlayer(player.id, year, player.joined ?? undefined, player.finished ?? undefined),
114	        clubSupporterService.getByPlayer(player.id),
115	        countrySupporterService.getByPlayer(player.id),
116	        playerRecordService.getForYearByPlayer(year, player.id),
117	        playerService.getPrevious(player.id),
118	        playerService.getNext(player.id),
119	        isAdmin ? playerService.getEmailDataById(player.id) : Promise.resolve(null),
120	    ]);
121	
122	    const trophies = new Map<TableName, PlayerRecordType[]>();
123	    await Promise.all(TableNameSchema.options.map(async (table) => {
124	        const winners = await playerRecordService.getWinners(table, year, player.id);
125	        trophies.set(table, winners);
126	    }));
127	
128	    return (
129	        <>
130	            <AutoRefresh channels={[FootyChannel.Players, FootyChannel.Results]} />
131	            <PlayerProfile
132	                key={player.id}
133	                player={player}
134	                introducedBy={introducedBy}
135	                year={year}
136	                history={history}
137	                lastPlayed={lastPlayed}
138	                lastWon={lastWon}
139	                clubs={clubs}
140	                countries={countries}
141	                activeYears={activeYears}
142	                record={record}
143	                prevPlayer={prevPlayer}
144	                nextPlayer={nextPlayer}
145	                trophies={trophies}
146	                isAuthenticated={isAuthenticated}
147	                isAdmin={isAdmin}
148	                playerData={playerData}
149	                onSendEmail={isAdmin ? sendEmail : undefined}
150	            />
151	        </>
152	    );
153	};
154	
155	export default PlayerPage;
