44	/**
45	 * Render the password reset flow for a user who has a reset token.
46	 */
47	export const PasswordResetForm = ({ token }: Props) => {
48	    const router = useRouter();
49	    const form = useForm<z.infer<typeof resetPasswordSchema>>({
50	        initialValues: {
51	            password: '',
52	            confirmPassword: '',
53	        },
54	        validate: zod4Resolver(resetPasswordSchema),
55	        validateInputOnBlur: true,
56	    });
57	
58	    /**
59	     * Submit a new password for the provided reset token and surface status via notifications.
60	     */
61	    const handleSubmit = async (values: z.infer<typeof resetPasswordSchema>) => {
62	        const id = notifications.show({
63	            loading: true,
64	            title: 'Resetting password',
65	            message: 'Updating your password...',
66	            autoClose: false,
67	            withCloseButton: false,
68	        });
69	
70	        try {
71	            const { status } = await authClient.resetPassword({
72	                newPassword: values.password,
73	                token,
74	            });
75	
76	            if (!status) {
77	                throw new ValidationError('Reset password returned an unsuccessful status.', {
78	                    publicMessage: 'Unable to reset password.',
79	                    details: {
80	                        tokenPresent: Boolean(token),
81	                    },
82	                });
83	            }
84	
85	            notifications.update({
86	                id,
87	                color: 'teal',
88	                title: 'Password updated',
89	                message: 'Your password has been reset successfully.',
90	                icon: <IconCheck size={config.notificationIconSize} />,
91	                loading: false,
92	                autoClose: config.notificationAutoClose,
93	            });
94	
95	            router.push('/footy/auth/signin');
96	        } catch (error) {
97	            const message = toPublicMessage(error, 'Unable to reset password.');
98	            notifications.update({
99	                id,
100	                color: 'red',
