36	export const SignIn = ({ admin, redirect }: Props) => {
37	    const [loading, setLoading] = useState(false);
38	    const [loginError, setLoginError] = useState<boolean>(false);
39	    const router = useRouter();
40	    const pathname = usePathname();
41	    const redirectPath = redirect ?? pathname;
42	    const socialRedirect = new URL(redirectPath, getPublicBaseUrl()).toString();
43	    const form = useForm({
44	        initialValues: {
45	            email: '',
46	            password: '',
47	        },
48	
49	        validateInputOnBlur: true,
50	
51	        validate: {
52	            email: (value) =>
53	                /^\S+@\S+\.\S+$/.test(value) ? null : 'Invalid email format',
54	            password: (value) =>
55	                value.length >= 8 ? null : 'Password must be at least 8 characters long',
56	        },
57	    });
58	
59	    const handleSignIn = async (values: { email: string; password: string }) => {
60	        setLoading(true);
61	        setLoginError(false);
62	
63	        try {
64	            await authClient.signIn.email({
65	                email: values.email,
66	                password: values.password,
67	            });
68	            router.push(redirectPath);
69	        }
70	        catch (error) {
71	            captureUnexpectedError(error, {
72	                layer: 'client',
73	                action: 'signInWithEmail',
74	                component: 'SignIn',
75	                route: pathname,
76	                extra: {
77	                    redirectPath,
78	                },
79	            });
80	            setLoginError(true);
81	        }
82	        finally {
83	            setLoading(false);
84	        }
85	    };
86	
87	    if (loading) {
88	        return (
89	            <Container>
90	                <Loader />
91	            </Container>
92	        );
93	    }
94	
95	    let title = 'Sign in to your account';
96	
97	    if (admin === true) {
98	        title = 'You must be logged in as an administrator to use this page.';
99	    } else if (admin === false) {
100	        title = 'You must be logged in to use this page.';
101	    }
102	
103	    const errorNotification = loginError ? (
104	        <Notification
105	            icon={<IconX size={config.notificationIconSize} />}
106	            color="red"
107	            onClose={() => setLoginError(false)}
108	        >
109	            Login failed. Please check your details and try again.
110	        </Notification>
111	    ) : null;
112	
113	    return (
114	        <Container size="xs" mt="xl" >
115	            <Stack mb="lg">
116	                <Title order={2} mb="xs" w="100%" ta="center">
117	                    {title}
118	                </Title>
119	                <Divider mb="xs" />
120	                <Group justify="center" w="100%" mb="md">
