27	export const ForgottenPasswordForm = () => {
28	    const form = useForm<ForgottenPasswordInput>({
29	        initialValues: {
30	            email: '',
31	        } satisfies ForgottenPasswordInput,
32	        validate: zod4Resolver(ForgottenPasswordSchema),
33	        validateInputOnBlur: true,
34	    });
35	
36	    const handleSubmit = async (
37	        values: typeof form.values,
38	    ) => {
39	        const normalizedEmail = values.email.trim().toLowerCase();
40	
41	        const id = notifications.show({
42	            loading: true,
43	            title: 'Requesting password reset',
44	            message: 'Checking for your account...',
45	            autoClose: false,
46	            withCloseButton: false,
47	        });
48	
49	        try {
50	            await authClient.requestPasswordReset({
51	                email: normalizedEmail,
52	                redirectTo: new URL('/footy/auth/reset-password', getPublicBaseUrl()).toString(),
53	            });
54	
55	            notifications.update({
56	                id,
57	                color: 'teal',
58	                title: 'Check your email',
59	                message: 'If that email is linked to an account, a reset link is on the way.',
60	                icon: <IconCheck size={config.notificationIconSize} />,
61	                loading: false,
62	                autoClose: config.notificationAutoClose,
63	            });
64	        } catch (err) {
65	            captureUnexpectedError(err, {
66	                layer: 'client',
67	                component: 'ForgottenPasswordForm',
68	                action: 'requestPasswordReset',
69	                route: '/footy/forgottenpassword',
70	                extra: {
71	                    email: normalizedEmail,
72	                },
73	            });
74	            notifications.update({
75	                id,
76	                color: 'red',
77	                title: 'Error',
78	                message: toPublicMessage(err, 'Unable to request a password reset right now.'),
79	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
80	                loading: false,
81	                autoClose: false,
82	                withCloseButton: true,
83	            });
84	        }
85	    };
86	
87	    return (
88	        <Box
89	            component="form"
90	            onSubmit={form.onSubmit(handleSubmit)}
91	            noValidate
92	        >
93	            <Stack gap="md">
94	                <Title order={2} mb="xs" w="100%" ta="center">
95	                    Forgotten Password
96	                </Title>
97	                <Divider mb="xs" />
98	                <EmailInput
99	                    label="Email"
100	                    description={[
101	                        "If the email is associated with an account, you'll receive a reset link.",
102	                        "Note that if you use Google or Microsoft sign-in, you won't have a password to reset.",
103	                    ].join(' ')}
104	                    required
105	                    {...form.getInputProps(`email`)}
106	                />
107	
108	                <Button type="submit" w="fit-content">
109	                    Send reset link
110	                </Button>
111	            </Stack>
112	        </Box>
113	    );
114	};
115	
116	const validateForgottenPasswordEmail = (value: string, ctx: z.RefinementCtx) => {
117	    if (!value) {
118	        ctx.addIssue({
119	            code: 'custom',
120	            message: 'Email is required',
121	        });
122	        return;
123	    }
124	
125	    if (!z.email().safeParse(value).success) {
126	        ctx.addIssue({
127	            code: 'custom',
128	            message: 'Invalid email',
129	        });
130	    }
131	};
132	
133	const ForgottenPasswordSchema = z.object({
134	    email: z.string().trim().toLowerCase().superRefine(validateForgottenPasswordEmail),
135	});
136	
137	type ForgottenPasswordInput = z.infer<typeof ForgottenPasswordSchema>;
