41	const formSchema = InvitationResponseInputSchema.omit({ token: true }).extend({
42	    comment: z.string().max(127).optional(),
43	});
44	type FormValues = z.infer<typeof formSchema>;
45	
46	const responseOptions = [
47	    { value: PlayerResponse.Yes, label: 'Yes' },
48	    { value: PlayerResponse.No, label: 'No' },
49	    { value: PlayerResponse.Dunno, label: 'Dunno' },
50	];
51	
52	/**
53	 * Responses that players can select themselves in this form.
54	 */
55	const playerEditableResponses = new Set<PlayerResponse>([
56	    PlayerResponse.Yes,
57	    PlayerResponse.No,
58	    PlayerResponse.Dunno,
59	]);
60	
61	/**
62	 * Returns the initial response value used by the editable select input.
63	 *
64	 * Player invitations can carry admin-only response values (for example
65	 * `Excused`) that should still be displayed in the summary, but players can
66	 * only submit Yes/No/Dunno from this form.
67	 *
68	 * @param response - Incoming invitation response from query details.
69	 * @returns The player-editable response value for the form select.
70	 */
71	function getInitialPlayerResponse(responseInput: GameInvitationResponseDetails['response']) {
72	    const response = responseInput &&
73	        playerEditableResponses.has(responseInput) ? responseInput : PlayerResponse.Yes;
74	
75	    return response;
76	}
77	
78	interface Props {
79	    details: GameInvitationResponseDetails;
80	    onSubmitGameInvitationResponse: SubmitGameInvitationResponseProxy;
81	}
82	
83	export const GameInvitationResponseForm = ({
84	    details,
85	    onSubmitGameInvitationResponse,
86	}: Props) => {
87	    const mounted = useMounted();
88	    const response = getInitialPlayerResponse(details.response);
89	    const [currentResponse, setCurrentResponse] = useState(details.response);
90	    const [currentComment, setCurrentComment] = useState(details.comment);
91	    const [canSubmitWithoutChanges, setCanSubmitWithoutChanges] = useState(!details.response);
92	
93	    const form = useForm<FormValues>({
94	        initialValues: {
95	            response,
96	            goalie: details.goalie ?? false,
97	            comment: details.comment ?? '',
98	        },
99	        validate: zod4Resolver(formSchema),
100	        validateInputOnBlur: true,
101	    });
102	
103	    /**
104	     * The form is dirty if the user has changed a field, or if there is no
105	     * saved response yet. In that case, submission is allowed without
106	     * interaction so users can quickly confirm the default Yes value. Once a
107	     * response has been saved, the button should disable again until the form
108	     * changes.
109	     */
110	    const isFormDirty = form.isDirty() || canSubmitWithoutChanges;
111	
112	    const handleSubmit = async (values: FormValues) => {
113	        const id = notifications.show({
114	            loading: true,
115	            title: 'Saving response',
116	            message: 'Saving your response...',
117	            autoClose: false,
118	            withCloseButton: false,
119	        });
120	
121	        try {
122	            await onSubmitGameInvitationResponse({
123	                token: details.token,
124	                response: values.response,
125	                goalie: values.goalie,
126	                comment: values.comment?.trim() ?? null,
127	            });
128	
129	            setCurrentResponse(values.response);
130	            setCurrentComment(values.comment?.trim() ?? '');
131	            setCanSubmitWithoutChanges(false);
132	
133	            notifications.update({
134	                id,
135	                color: 'teal',
136	                title: 'Response saved',
137	                message: 'Your response has been updated.',
138	                icon: <IconCheck size={config.notificationIconSize} />,
139	                loading: false,
140	                autoClose: config.notificationAutoClose,
141	            });
142	        } catch (error) {
143	            captureUnexpectedError(error, {
144	                layer: 'client',
145	                component: 'GameInvitationResponseForm',
146	                action: 'submitResponse',
147	                route: '/footy/game/[id]',
148	                extra: {
149	                    playerId: details.playerId,
150	                    gameDayId: details.gameDayId,
151	                    response: values.response,
152	                },
153	            });
154	            const message = error instanceof Error ? error.message : 'Failed to save response';
155	            notifications.update({
156	                id,
157	                color: 'red',
158	                title: 'Error',
159	                message,
160	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
161	                loading: false,
162	                autoClose: false,
163	                withCloseButton: true,
164	            });
165	        }
166	    };
167	
168	    const responseColor = {
169	        [PlayerResponse.Yes.toString()]: 'green',
170	        [PlayerResponse.No.toString()]: 'red',
171	        [PlayerResponse.Dunno.toString()]: 'grey',
172	    } as const;
173	    const displayResponse = currentResponse ? (
174	        <Badge color={responseColor[currentResponse.toString()]} variant="filled" size="sm">
175	            {currentResponse}
176	        </Badge>
177	    ) : (
178	        <Badge color="grey" variant="filled" size="sm">
179	            No response yet
180	        </Badge>
181	    );
182	    const displayComment = currentComment ? `("${currentComment}")` : '';
183	    const playerLink = details.playerLogin ? `/footy/player/${details.playerLogin}` : `/footy/player/${details.playerId}`;
184	
185	    return (
186	        <Box component="form" onSubmit={form.onSubmit(handleSubmit)}>
187	            <Stack gap="md">
188	                <Title order={2} mb="xs" w="100%" ta="center">
189	                    {currentResponse ? 'Thanks for Your Response' : 'Enter Your Response'}
190	                </Title>
191	                <Divider mb="xs" />
192	                <Flex align="center" gap="md" wrap="wrap">
193	                    <Avatar
194	                        src={`/api/footy/player/${details.playerId}/mugshot`}
195	                        alt={details.playerName}
196	                        size={48}
197	                        radius="xl"
198	                    />
199	                    <Anchor href={playerLink}>{details.playerName}</Anchor>: {displayResponse} {displayComment}
200	                </Flex>
201	                <Select
202	                    label="Response"
203	                    data={responseOptions}
204	                    value={form.values.response}
205	                    /* v8 ignore next -- allowDeselect={false} means value is never null */
206	                    onChange={(value) => form.setFieldValue('response', (value ?? PlayerResponse.Yes))}
207	                    allowDeselect={false}
208	                />
209	                <Checkbox
210	                    label="Goalie"
211	                    {...form.getInputProps('goalie', { type: 'checkbox' })}
212	                />
213	                <TextInput
214	                    label="Optional comment/excuse"
215	                    maxLength={127}
216	                    {...form.getInputProps('comment')}
217	                />
218	                <Button type="submit" w="fit-content" loading={!mounted} disabled={!isFormDirty}>
219	                    Save Response
220	                </Button>
221	                <Text mt="xl">
222	                    You can change it later if you need to, even if the teams have been picked - either by clicking
223	                    on the link in the email you received, or by logging in to the site at{' '}
224	                    <Anchor href={`/footy/game/${details.gameDayId}`}>the game page</Anchor>. If you can&apos;t get to
225	                    a computer, message Jon on <strong>{config.organiserPhoneNumber}</strong>.
226	                </Text>
227	            </Stack>
228	        </Box>
229	    );
230	};
