32	        } satisfies ForgottenPasswordInput,
33	        validate: zod4Resolver(ForgottenPasswordSchema),
34	        validateInputOnBlur: true,
35	    });
36	
37	    const handleSubmit = async (
38	        values: typeof form.values,
39	    ) => {
40	        const normalizedEmail = values.email.trim().toLowerCase();
41	
42	        const id = notifications.show({
43	            loading: true,
44	            title: 'Requesting password reset',
45	            message: 'Checking for your account...',
46	            autoClose: false,
47	            withCloseButton: false,
48	        });
49	
50	        try {
51	            await authClient.requestPasswordReset({
52	                email: normalizedEmail,
53	                redirectTo: new URL('/footy/auth/reset-password', getPublicBaseUrl()).toString(),
54	            });
55	
56	            notifications.update({
57	                id,
58	                color: 'teal',
59	                title: 'Check your email',
60	                message: 'If that email is linked to an account, a reset link is on the way.',
61	                icon: <IconCheck size={config.notificationIconSize} />,
62	                loading: false,
63	                autoClose: config.notificationAutoClose,
64	            });
65	        } catch (err) {
66	            captureUnexpectedError(err, {
67	                layer: 'client',
68	                component: 'ForgottenPasswordForm',
69	                action: 'requestPasswordReset',
70	                route: '/footy/forgottenpassword',
71	                extra: {
