73	                },
74	            });
75	            notifications.update({
76	                id,
77	                color: 'red',
78	                title: 'Error',
79	                message: toPublicMessage(err, 'Unable to request a password reset right now.'),
80	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
81	                loading: false,
82	                autoClose: false,
83	                withCloseButton: true,
84	            });
85	        }
86	    };
87	
88	    return (
89	        <Paper w="100%" maw="35rem" p="xl">
90	            <Box
91	                component="form"
92	                onSubmit={form.onSubmit(handleSubmit)}
93	                noValidate
94	            >
95	                <Stack gap="md">
96	                    <Title order={2} mb="xs" w="100%" ta="center">
97	                        Forgotten Password
98	                    </Title>
99	                    <Divider mb="xs" />
100	                    <EmailInput
