10	import classes from './DebugFontSizes.module.css';
11	
12	export interface FontSizeTarget {
13	    /** Human-readable name shown in the overlay */
14	    label: string;
15	    /** CSS selector used to find a live element to measure */
16	    selector: string;
17	}
18	
19	export interface DebugFontSizesProps {
20	    /** Elements to sample the computed font-size of, e.g. fluid/clamp() text */
21	    targets: FontSizeTarget[];
22	}
23	
24	interface Sample extends FontSizeTarget {
25	    fontSizePx: number | null;
26	    matches: number;
27	}
28	
29	function getRootFontSizePx(): number {
30	    if (typeof document === 'undefined') return 16;
31	    return parseFloat(getComputedStyle(document.documentElement).fontSize);
32	}
33	
34	function measure(targets: FontSizeTarget[]): Sample[] {
35	    return targets.map(({ label, selector }) => {
36	        const elements = document.querySelectorAll<HTMLElement>(selector);
37	        const first = elements[0];
38	
39	        return {
40	            label,
41	            selector,
42	            fontSizePx: first ? parseFloat(getComputedStyle(first).fontSize) : null,
43	            matches: elements.length,
44	        };
45	    });
46	}
47	
48	export const DebugFontSizes = ({ targets }: DebugFontSizesProps) => {
49	    const [viewportWidth, setViewportWidth] = useState(0);
50	    const [pxPerEm, setPxPerEm] = useState(getRootFontSizePx);
51	    const [samples, setSamples] = useState<Sample[]>([]);
52	
53	    useEffect(() => {
54	        const update = () => {
55	            setViewportWidth(window.innerWidth);
56	            // Root font size can change with browser zoom, so re-read it on
57	            // every update rather than once - clamp() reacts to both.
58	            setPxPerEm(getRootFontSizePx());
59	            setSamples(measure(targets));
60	        };
61	
62	        update();
63	        window.addEventListener('resize', update);
64	        // Pinch-zoom on mobile/trackpad doesn't always fire `resize`.
65	        window.visualViewport?.addEventListener('resize', update);
66	
67	        return () => {
68	            window.removeEventListener('resize', update);
69	            window.visualViewport?.removeEventListener('resize', update);
70	        };
71	    }, [targets]);
72	
73	    return (
74	        <Container className={classes.div}>
75	            <Text className={classes.p}>
76	                🔤 <strong>Font sizes</strong> — viewport: {viewportWidth}px / {(viewportWidth / pxPerEm).toFixed(2)}em
77	            </Text>
78	            <Table className={classes.table}>
79	                <TableTbody>
80	                    {samples.map((sample) => (
81	                        <TableTr key={sample.selector}>
82	                            <TableTd className={classes.td}>{sample.label}</TableTd>
83	                            <TableTd className={classes.td}>
84	                                {sample.fontSizePx === null ?
85	                                    'no match' :
86	                                    `${sample.fontSizePx.toFixed(2)}px / ${(sample.fontSizePx / pxPerEm).toFixed(3)}rem`}
87	                            </TableTd>
88	                            <TableTd className={classes.td}>
89	                                {sample.matches > 1 ? `(${sample.matches} matches)` : null}
90	                            </TableTd>
91	                        </TableTr>
92	                    ))}
93	                </TableTbody>
94	            </Table>
95	        </Container>
96	    );
97	};
