133	        const supporters = supportersByAtlasName.get(hoveredCountry) ?? [];
134	        const grouped = new Map<string, CountrySupporterWithPlayerDataType[]>();
135	        for (const s of supporters) {
136	            const key = s.country.name;
137	            const arr = grouped.get(key) ?? [];
138	            arr.push(s);
139	            grouped.set(key, arr);
140	        }
141	        return Array.from(grouped.entries());
142	    }, [hoveredCountry, supportersByAtlasName]);
143	
144	    /** Cancels any pending delayed close. */
145	    const cancelClose = useCallback(() => {
146	        if (closeTimerRef.current) {
147	            clearTimeout(closeTimerRef.current);
148	            closeTimerRef.current = null;
149	        }
150	    }, []);
151	
152	    /** Schedules a delayed popover close unless the dropdown is hovered. */
153	    const scheduleClose = useCallback(() => {
154	        cancelClose();
155	        closeTimerRef.current = setTimeout(() => {
156	            /* c8 ignore next — onMouseEnter always cancels the timer before setting dropdownHoveredRef; the timer can only fire while the flag is false */
157	            if (!dropdownHoveredRef.current) {
158	                setPopoverOpen(false);
159	                setHoveredCountry(null);
160	            }
161	        }, CLOSE_DELAY_MS);
162	    }, [cancelClose]);
163	
164	    /**
165	     * Handles mouse-enter on a highlighted country path. Anchors the popover
166	     * to the country's projected centroid for a stable position.
167	     */
168	    const handleMouseEnter = useCallback(
169	        (atlasName: string) => {
170	            cancelClose();
171	            const lowerName = atlasName.toLowerCase();
172	            const centroid = centroidsRef.current.get(lowerName);
173	            /* v8 ignore next -- centroid is always pre-computed before a D3 mouseenter can fire */
174	            if (centroid) {
175	                setPopoverPos(centroid);
176	            }
177	            setHoveredCountry(lowerName);
178	            setPopoverOpen(true);
179	        },
180	        [cancelClose],
181	    );
182	
183	    /** Handles mouse-leave on a highlighted country path. */
184	    const handleMouseLeave = useCallback(() => {
185	        scheduleClose();
186	    }, [scheduleClose]);
187	
188	    useEffect(() => {
189	        /* c8 ignore next — svgRef is always attached before effects run; the null path is a defensive guard only */
190	        if (!svgRef.current) return;
191	
192	        const svg = select(svgRef.current);
193	        svg.selectAll('*').remove();
194	
195	        const projection = geoMercator()
196	            .center([0, 20])
197	            .scale(width / 6.5)
198	            .translate([width / 2, height / 2]);
199	
200	        const path = geoPath().projection(projection);
201	
202	        const g = svg.append('g');
203	
204	        const supportedNames = new Set(supportersByAtlasName.keys());
205	
206	        void json<Topology>('/countries-110m.json').then((topology) => {
207	            if (!topology) return undefined;
208	
209	            const geojson = topojson.feature(
210	                topology,
211	                topology.objects.countries as GeometryCollection,
212	            );
213	
214	            type CountryFeature = GeoJSON.Feature<GeoJSON.Geometry, CountryProperties>;
215	            const features = geojson.features as CountryFeature[];
216	
217	            /* Pre-compute projected centroids for highlighted countries so
218	               the popover can be anchored to a stable position. */
219	            const newCentroids = new Map<string, { x: number; y: number }>();
220	            for (const f of features) {
221	                const name = (f.properties?.name ?? '').toLowerCase();
222	                if (supportedNames.has(name)) {
223	                    const [cx, cy] = path.centroid(f);
224	                    newCentroids.set(name, { x: cx, y: cy });
225	                }
226	            }
227	            centroidsRef.current = newCentroids;
228	
229	            g.selectAll<SVGPathElement, CountryFeature>('path')
230	                .data(features)
231	                .enter()
232	                .append('path')
233	                .attr('d', path)
234	                .attr('fill', (d) => {
235	                    const name = (d.properties?.name ?? '').toLowerCase();
236	                    return supportedNames.has(name) ?
237	                        HIGHLIGHT_FILL :
238	                        DEFAULT_FILL;
239	                })
240	                .attr('stroke', STROKE_COLOUR)
241	                .attr('stroke-width', STROKE_WIDTH)
242	                .on('mouseenter', function (_event: MouseEvent, d) {
243	                    const name = (d.properties?.name ?? '').toLowerCase();
244	                    if (supportedNames.has(name)) {
245	                        handleMouseEnter(name);
246	                    }
247	                })
248	                .on('mouseleave', function () {
249	                    handleMouseLeave();
250	                });
251	
252	            return undefined;
253	        });
254	    }, [countries, width, height, supportersByAtlasName, handleMouseEnter, handleMouseLeave]);
255	
256	    return (
257	        <Box pos="relative" data-testid="player-country-map">
258	            <svg
259	                ref={svgRef}
260	                width={width}
261	                height={height}
262	            />
263	            <Popover
264	                opened={popoverOpen}
265	                position="bottom"
266	                withArrow
267	                shadow="md"
268	                withinPortal={false}
269	            >
270	                <Popover.Target>
271	                    <Box
272	                        pos="absolute"
273	                        left={popoverPos.x}
274	                        top={popoverPos.y}
275	                        w={1}
276	                        h={1}
277	                        pe="none"
278	                    />
279	                </Popover.Target>
280	                <Popover.Dropdown
281	                    data-testid="country-popover-dropdown"
282	                    onMouseEnter={() => {
283	                        dropdownHoveredRef.current = true;
284	                        cancelClose();
285	                    }}
286	                    onMouseLeave={() => {
287	                        dropdownHoveredRef.current = false;
288	                        scheduleClose();
289	                    }}
290	                    pe="auto"
291	                >
292	                    <ScrollArea.Autosize mah={POPOVER_MAX_HEIGHT}>
293	                        <Stack gap="xs">
294	                            {hoveredGroups.map(([countryName, supporters]) => (
295	                                <Stack key={countryName} gap={4}>
296	                                    <Text size="xs" fw={700}>{countryName}</Text>
297	                                    {supporters.map((s) => (
298	                                        <Anchor
299	                                            key={s.playerId}
300	                                            href={`/footy/player/${s.playerId}`}
301	                                            underline="never"
302	                                        >
303	                                            <Group gap="xs" wrap="nowrap">
304	                                                <Image
305	                                                    src={`/api/footy/player/${s.playerId}/mugshot`}
306	                                                    alt={s.player.name ?? `Player ${s.playerId}`}
307	                                                    w={MUGSHOT_SIZE}
308	                                                    h={MUGSHOT_SIZE}
309	                                                    radius="xl"
310	                                                />
311	                                                <Text size="sm">
312	                                                    {s.player.name ?? `Player ${s.playerId}`}
313	                                                </Text>
314	                                            </Group>
315	                                        </Anchor>
316	                                    ))}
317	                                </Stack>
318	                            ))}
319	                        </Stack>
320	                    </ScrollArea.Autosize>
321	                </Popover.Dropdown>
322	            </Popover>
323	        </Box>
324	    );
325	};
