64	        const preferredExtraEmails = verifiedExtraEmails.length > 0 ? verifiedExtraEmails : player.extraEmails;
65	        return [player.accountEmail, ...preferredExtraEmails.map((playerEmail) => playerEmail.email)];
66	    }).map(normalizeEmail).filter((email) => email.length > 0))).join(',');
