158	                            <RichTextEditor.Italic />
159	                            <RichTextEditor.Underline />
160	                            <RichTextEditor.Strikethrough />
161	                            <RichTextEditor.ClearFormatting />
162	                            <RichTextEditor.Highlight />
163	                            <RichTextEditor.Code />
164	                        </RichTextEditor.ControlsGroup>
165	
166	                        <RichTextEditor.ControlsGroup>
